7	/**
8	 * Soft duplicate detection on create. The hard duplicate check ({@link RejectDuplicateIdentity})
9	 * has already rejected any owner whose whole {@code identityKey} matches an existing owner's, so
10	 * by the time this step runs the new owner is guaranteed not to be a hard duplicate.
11	 *
12	 * <p>This step flags a weaker, non-rejecting signal: a new owner that is <em>not</em> a hard
13	 * duplicate but still shares an existing owner's {@code lastName} (case-insensitive) and
14	 * {@code postcode} while carrying a <em>different</em> telephone. In that case the owner is
15	 * still created, but {@code possibleDuplicate} is set true and {@code possibleDuplicateOf} is
16	 * set to the matching owner's id (the lowest-id match when several exist). Otherwise
17	 * {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
18	 *
19	 * <p>A declared household member ({@code sharesHousehold} true) is never flagged: it reached this
20	 * step only because it deliberately bypassed the duplicate block, so sharing an existing owner's
21	 * last name and postcode is expected rather than a suspected duplicate.
22	 *
23	 * <p>Runs after the telephone and postcode have been normalized/assigned and before
24	 * {@link SaveOwner}, so the flags are fixed at creation time and returned on later reads.
25	 */
26	public class FlagPossibleDuplicate {
27	
28	    public void service(@Val Owner owner, @Val Boolean sharesHousehold, OwnerRepository ownerRepository) {
29	        String lastName = owner.getLastName();
30	        String postcode = owner.getPostcode();
31	        String telephone = normalizedTelephone(owner);
32	
33	        owner.setPossibleDuplicate(false);
34	        owner.setPossibleDuplicateOf(null);
35	
36	        if (Boolean.TRUE.equals(sharesHousehold)) {
37	            // Declared household member: expected to share a household, not a suspected duplicate.
38	            return;
39	        }
40	
41	        if (lastName == null || postcode == null) {
42	            return;
43	        }
44	
45	        Integer matchId = null;
46	        for (Owner existing : ownerRepository.findAll()) {
47	            if (existing.getId() == null || existing.getId().equals(owner.getId())) {
48	                continue;
49	            }
50	            if (!lastName.equalsIgnoreCase(existing.getLastName())) {
51	                continue;
52	            }
53	            if (!postcode.equals(existing.getPostcode())) {
54	                continue;
55	            }
56	            // A different telephone is what distinguishes a soft match from a hard
57	            // (identityKey) duplicate, which has already been rejected upstream. Compare
58	            // through the same normalization as the hard check so the two can't drift.
59	            if (telephone.equals(normalizedTelephone(existing))) {
60	                continue;
61	            }
62	            if (matchId == null || existing.getId() < matchId) {
63	                matchId = existing.getId();
64	            }
65	        }
66	
67	        if (matchId != null) {
68	            owner.setPossibleDuplicate(true);
69	            owner.setPossibleDuplicateOf(matchId);
70	        }
71	    }
72	
73	    /**
74	     * The owner's telephone in the same normalized form {@link OwnerIdentity} compares on:
75	     * the E.164 value via {@link OwnerTelephones#toE164}, falling back to the stored raw value
76	     * (or empty) when it cannot be normalized, so a stored value that predates the pipeline
77	     * still compares correctly.
78	     */
79	    private static String normalizedTelephone(Owner owner) {
80	        String telephone = OwnerTelephones.toE164(owner.getTelephone());
81	        if (telephone == null) {
82	            telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
83	        }
84	        return telephone;
85	    }
86	}
